FREE_VAR_MISMATCH = 'Gold has 2 free variable(s) (e : EMPLOYEE_ID, j2 : JOB_TITLE) but Predicted has 3 (emp_id : EMPLOYEE_ID, job_title : JOB_TITLE, job_id : JOB_ID): their answers have different arities'
